def maskPII(S: str) -> str:
    if '@' in S:
        parts = S.lower().split('@')
        return f"{parts[0][0]}*****{parts[0][-1]}@{parts[1]}"
    else:
        digits = [d for d in S if d.isdigit()]
        local = "***-***-{}".format(''.join(digits[-4:]))
        if len(digits) == 10:
            return local
        else:
            return "+{}-".format('*' * (len(digits) - 10)) + local
